export default `@charset "UTF-8";:root{--navy: #07111f;--navy-2: #0b1727;--blue: #0062df;--blue-light: #35a1ff;--ink: #101b2c;--muted: #56677e;--pale: #f3f8ff;--white: #fff;--line: #e2eaf4;--radius: 18px;--shadow: 0 14px 38px rgba(15, 39, 71, .08);--header-height: 78px;--section-pad-top: 82px;--anchor-gap: 14px}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:max(0px,var(--header-height) + var(--anchor-gap) - var(--section-pad-top))}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;color:var(--ink);background:#fff;line-height:1.6;overflow-x:clip}h1,h2,h3{overflow-wrap:break-word}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button,a{-webkit-tap-highlight-color:transparent}:focus-visible{outline:3px solid #73baff;outline-offset:3px}.container{width:min(1160px,100% - 40px);margin-inline:auto}.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:48px;padding:0 22px;border:1px solid transparent;border-radius:11px;background:var(--blue);color:#fff;font-size:15px;font-weight:650;cursor:pointer;transition:transform .2s,background .2s,box-shadow .2s}.btn:hover{transform:translateY(-2px);background:#004fb5;box-shadow:0 9px 24px #087cff3d}.btn-outline{background:transparent;border-color:#fff9;color:#fff}.btn-outline:hover{background:#ffffff1a}.eyebrow{display:flex;align-items:center;gap:10px;margin:0 0 14px;color:var(--blue);font-size:13px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.eyebrow:before{content:"";width:25px;height:2px;background:currentColor}section{padding:var(--section-pad-top) 0}.section-head{max-width:560px;margin-bottom:28px}.section-head .eyebrow{color:var(--blue);margin-bottom:10px}.section-head p{color:var(--muted);margin:15px 0 0;font-size:16px}h2{margin:0;font-size:clamp(28px,3.6vw,40px);line-height:1.12;letter-spacing:-.035em}.brand{display:inline-flex;align-items:center;gap:11px;flex-shrink:0}.brand-mark{width:50px;height:50px}.brand-mark img{width:100%;height:100%;object-fit:cover}.brand-name{font-size:21px;font-weight:850;line-height:1.05;letter-spacing:.045em}.brand-sub{display:block;margin-top:5px;font-size:12px;font-weight:600;letter-spacing:.36em;color:#c6d3e3}.project-tag{color:var(--blue);font-size:13px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}@media(max-width:720px){:root{--header-height: 70px;--section-pad-top: 62px}.container{width:min(100% - 32px,560px)}}[dir=rtl] .nav{direction:ltr}[dir=rtl] .nav-links{text-align:right}[dir=rtl] .demo-track,[dir=rtl] .portfolio-track{direction:ltr}[dir=rtl] .demo-grid,[dir=rtl] .portfolio-grid{direction:rtl}[dir=rtl] .btn>span[aria-hidden=true]{display:inline-block;transform:scaleX(-1)}[dir=rtl] .service-card:before,[dir=rtl] .stat:before{transform-origin:right}@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition-duration:.01ms!important;animation-duration:.01ms!important}}
`;